window.BENTO_RECIPE_LIBRARY=[{"id":"jp_001","title":"Oyakodon","japaneseName":"親子丼","romanization":"oyakodon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":20,"total":35,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"small skillet or donburi pan","ingredients":["300 g cooked Japanese short-grain rice","250 g boneless chicken thigh, cut into bite-size pieces","1/2 medium onion, thinly sliced","3 large eggs, lightly beaten","160 ml dashi","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sugar","2 tbsp mitsuba or sliced scallion, optional"],"steps":["Cook the rice first and keep it hot. Cut the chicken into similar-size pieces so it cooks evenly; slice the onion and lightly beat the eggs without fully homogenizing them.","Combine dashi, soy sauce, mirin, and sugar in a small skillet or donburi pan. Add the onion and bring to a gentle simmer for 2–3 minutes.","Add the chicken in a single layer. Simmer over medium-low heat for about 5–7 minutes, turning once, until the chicken is cooked through and the onion is tender.","Pour about two-thirds of the beaten egg evenly over the chicken. Cover and cook gently for about 45–60 seconds, until mostly set.","Add the remaining egg and mitsuba or scallion. Cover again for 20–40 seconds; the egg should be softly set rather than dry. Use pasteurized eggs if you prefer a very soft finish.","Divide hot rice between bowls and slide the chicken-and-egg mixture over the top with its cooking juices. Serve immediately."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Oyakodon 親子丼 Japanese food","Oyakodon Japanese food"]},{"id":"jp_002","title":"Gyudon","japaneseName":"牛丼","romanization":"gyudon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":18,"total":28,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet","ingredients":["300 g cooked Japanese short-grain rice","250 g thinly sliced beef","1/2 medium onion, thinly sliced","180 ml dashi or water","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sake","1 tbsp sugar","pickled red ginger, optional","2 soft-cooked or pasteurized eggs, optional"],"steps":["Keep the cooked rice hot. Separate the beef slices so they do not clump and slice the onion thinly.","Add dashi, soy sauce, mirin, sake, and sugar to a skillet. Bring to a gentle simmer, then add the onion and cook for 4–5 minutes until softened.","Add the beef in loose layers. Simmer 3–5 minutes, skimming any foam, until the beef is just cooked and tender; avoid boiling hard because thin beef toughens quickly.","Taste the broth and reduce for another minute if it is too thin. It should be savory-sweet and still spoonable.","Divide rice between bowls, arrange the beef and onion on top, and spoon over enough broth to season the rice without flooding it.","Finish with pickled ginger and, if desired, a safely handled soft-cooked or pasteurized egg."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Gyudon 牛丼 Japanese food","Gyudon Japanese food"]},{"id":"jp_003","title":"Katsudon","japaneseName":"カツ丼","romanization":"katsudon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":25,"total":45,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"frying pan and small skillet","ingredients":["300 g cooked Japanese short-grain rice","2 boneless pork loin cutlets, about 120 g each","1/2 tsp salt and 1/4 tsp black pepper","3 tbsp all-purpose flour","1 egg, beaten, for breading","60 g panko breadcrumbs","neutral oil for frying, as needed","1/2 onion, thinly sliced","160 ml dashi","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sugar","2 eggs, lightly beaten","mitsuba or scallion, optional"],"steps":["Pat the pork dry, lightly season, and pound to an even thickness if needed.","Coat in flour, then beaten egg, then panko, pressing gently so the crumbs adhere.","Heat 2–3 cm of oil to about 170°C. Fry the pork until golden and cooked through, roughly 3–4 minutes per side depending on thickness. Drain on a rack and rest for 3 minutes.","Slice each tonkatsu into strips while keeping the cutlet together.","In a clean skillet, simmer dashi, soy sauce, mirin, sugar, and onion for 4–5 minutes until the onion softens.","Place the sliced cutlet over the onions. Pour the beaten eggs around and partly over the cutlet; cover and cook on low for 45–90 seconds until softly set.","Place hot rice in bowls and carefully slide the katsudon topping over each bowl. Garnish with mitsuba or scallion."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Katsudon カツ丼 Japanese food","Katsudon Japanese food"]},{"id":"jp_004","title":"Tendon","japaneseName":"天丼","romanization":"tendon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep pot or fryer","ingredients":["300 g cooked Japanese short-grain rice","4 medium shrimp, peeled and deveined","4 thin slices kabocha squash","4 green beans","4 slices eggplant","70 g cake flour or all-purpose flour","1 small egg","120 ml ice-cold water","neutral oil for deep-frying, as needed","120 ml dashi","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sugar"],"steps":["Prepare the tempura sauce first: simmer dashi, soy sauce, mirin, and sugar for 2–3 minutes, then keep warm.","Dry the shrimp and vegetables thoroughly. Make shallow cuts on the underside of the shrimp and gently straighten them to reduce curling.","Heat frying oil to about 170–175°C.","Mix the egg with ice-cold water, then add flour and stir only a few strokes; lumps are desirable and overmixing makes the batter heavy.","Lightly dust the ingredients with flour if needed, dip in batter, and fry in small batches until crisp and just cooked. Drain on a rack, not paper towels, to preserve crispness.","Dip or lightly brush each piece of hot tempura with the warm tendon sauce.","Divide rice between bowls, arrange the tempura on top, and spoon over a little more sauce. Serve immediately so the coating stays crisp."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","shellfish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Tendon 天丼 Japanese food","Tendon Japanese food"]},{"id":"jp_005","title":"Soboro Don","japaneseName":"そぼろ丼","romanization":"soboro don","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":12,"cook":18,"total":30,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"2 skillets","ingredients":["300 g cooked Japanese short-grain rice","250 g ground chicken","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sake","1 tbsp sugar","3 eggs","1 tbsp sugar for eggs","pinch of salt","60 g blanched green beans or spinach, finely cut"],"steps":["Keep the rice hot. Mix ground chicken with soy sauce, mirin, sake, and sugar in a cold skillet before turning on the heat; this helps create fine crumbles.","Cook over medium heat, stirring continuously and breaking the chicken into small grains, until the liquid is mostly absorbed and the chicken is fully cooked, about 7–9 minutes.","Beat the eggs with sugar and a pinch of salt. Cook in a clean nonstick skillet over low-medium heat, stirring constantly with chopsticks or a spatula to make small, soft curds.","Season and finely chop the blanched green beans or spinach.","Divide rice between bowls. Arrange the chicken soboro, egg soboro, and green vegetable in separate sections over the rice.","Serve warm; the contrasting colors and textures are part of the classic presentation."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Soboro Don そぼろ丼 Japanese food","Soboro Don Japanese food"]},{"id":"jp_006","title":"Unadon","japaneseName":"鰻丼","romanization":"unadon","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":12,"total":22,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"small saucepan and broiler or skillet","ingredients":["300 g cooked Japanese short-grain rice","2 cooked unagi kabayaki fillets, about 100–120 g each","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sake","1 tbsp sugar","sansho pepper, optional"],"steps":["If using packaged cooked unagi, gently wipe away excess thick sauce if it is overly sweet, then pat dry.","Combine soy sauce, mirin, sake, and sugar in a small saucepan. Simmer 3–4 minutes until glossy but still fluid.","Warm the unagi under a broiler or in a covered skillet over low heat until heated through. Brush with the sauce during the final minute; avoid overcooking because eel dries quickly.","Divide hot rice between bowls and spoon a small amount of sauce over the rice.","Place the glazed eel on top and brush with a final thin layer of sauce.","Serve immediately with sansho pepper if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Unadon 鰻丼 Japanese food","Unadon Japanese food"]},{"id":"jp_007","title":"Takikomi Gohan","japaneseName":"炊き込みご飯","romanization":"takikomi gohan","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":40,"total":60,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"rice cooker or heavy pot","ingredients":["2 rice-cooker cups Japanese short-grain rice, about 300 g","150 g boneless chicken thigh, small pieces","1 small carrot, cut into thin matchsticks","80 g shiitake mushrooms, sliced","60 g gobo, thinly shaved, optional","1 piece aburaage, blanched and sliced","2 tbsp soy sauce","2 tbsp mirin","1 tbsp sake","dashi, enough to reach the rice-cooker 2-cup line","2 tbsp mitsuba or scallion"],"steps":["Rinse the rice until the water is mostly clear, then drain for about 15 minutes.","Prepare the chicken and vegetables in small pieces so they cook at the same rate as the rice. Briefly soak shaved gobo in water and drain.","Put the drained rice in the rice cooker.","Add soy sauce, mirin, and sake, then add dashi to the normal 2-cup water line and stir once.","Spread chicken, carrot, mushrooms, gobo, and aburaage evenly over the rice. Do not stir them deeply into the rice, which can cause uneven cooking.","Cook on the regular white-rice setting. When finished, rest unopened for 10 minutes.","Open, gently fold the toppings through the rice from the bottom, and garnish with mitsuba or scallion."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Takikomi Gohan 炊き込みご飯 Japanese food","Takikomi Gohan Japanese food"]},{"id":"jp_008","title":"Onigiri","japaneseName":"おにぎり","romanization":"onigiri","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":5,"total":20,"servings":6,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"rice cooker","ingredients":["600 g freshly cooked Japanese short-grain rice","1/2 tsp fine salt","2 sheets nori, cut into strips","3 tbsp flaked salted salmon, optional filling","2 tbsp umeboshi flesh, optional filling","2 tbsp tuna mixed with 1 tbsp Japanese mayonnaise, optional filling"],"steps":["Prepare fillings before handling the rice. Use fillings that are cooked, pickled, or otherwise safe for room-temperature handling if the onigiri will be packed.","Let freshly cooked rice cool just enough to handle while it is still warm; cold rice is harder to shape and does not bind as well.","Wet clean hands with water and rub a tiny pinch of salt over the palms, or use a clean sheet of plastic wrap for shaping.","Place about 90–100 g rice in one hand, make a small hollow, add 1–2 teaspoons filling, then cover with rice.","Press gently into a triangle or round shape, rotating as you press. Do not compact so firmly that the grains become mashed.","Wrap with nori just before serving for crisp nori, or earlier if you prefer it soft. Cool promptly before packing into a closed lunch container."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","egg"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Onigiri おにぎり Japanese food","Onigiri Japanese food"]},{"id":"jp_009","title":"Omurice","japaneseName":"オムライス","romanization":"omuraisu","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":20,"total":35,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"nonstick skillet","ingredients":["300 g cooked Japanese short-grain rice, preferably cooled","150 g boneless chicken thigh, diced","1/2 onion, diced","60 g green peas","3 tbsp ketchup, plus more to serve","1 tsp Worcestershire sauce","1 tbsp butter or neutral oil","4 large eggs","2 tbsp milk","pinch of salt","1 tsp butter for eggs"],"steps":["Dice the chicken and onion small. Break up any clumps in the cooked rice before starting.","Heat butter or oil in a skillet over medium heat. Cook chicken until no longer pink, then add onion and cook until softened.","Add rice and stir-fry until hot. Stir in ketchup and Worcestershire sauce and cook for another minute so the ketchup loses its raw taste. Fold in peas, then shape the rice into two oval mounds on plates.","For each omelet, beat 2 eggs with 1 tablespoon milk and a pinch of salt. Melt a little butter in a nonstick pan over medium-low heat.","Pour in the eggs and stir briefly to create fine curds, then stop stirring and let the base set while the top remains softly moist.","Slide or drape the omelet over the ketchup rice. Finish with a thin line of ketchup and serve immediately."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","milk","gluten"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Omurice オムライス Japanese food","Omurice Japanese food"]},{"id":"jp_010","title":"Ochazuke","japaneseName":"お茶漬け","romanization":"ochazuke","category":"Rice & Donburi","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":8,"cook":5,"total":13,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"kettle or saucepan","ingredients":["300 g hot cooked Japanese short-grain rice","350 ml hot green tea or light dashi","80 g cooked salted salmon, flaked","1 tbsp sliced scallion","1/2 sheet nori, shredded","1 tsp toasted sesame seeds","2 tsp arare rice crackers, optional","wasabi, optional"],"steps":["Place hot rice in two bowls, keeping the surface loose rather than packed.","Arrange flaked salmon, scallion, nori, sesame, and arare over the rice.","Heat green tea or light dashi until steaming but not aggressively boiling.","Pour the hot liquid around and over the toppings immediately before eating.","Add a small dab of wasabi if desired and eat while hot."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","sesame"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Ochazuke お茶漬け Japanese food","Ochazuke Japanese food"]},{"id":"jp_011","title":"Shoyu Ramen","japaneseName":"醤油ラーメン","romanization":"shoyu ramen","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":45,"total":70,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"2 saucepans","ingredients":["2 portions fresh ramen noodles","700 ml chicken stock","10 g kombu","10 g dried shiitake mushrooms","3 tbsp soy sauce","1 tbsp mirin","1 tbsp sake","1 tsp sugar","1 tsp sesame oil","2 soft-boiled eggs","4 slices chashu or cooked pork","2 tbsp sliced scallion","nori and menma, optional"],"steps":["Soak kombu and dried shiitake in the chicken stock for 20 minutes.","Warm slowly, remove kombu just before a full boil, then simmer the shiitake for 10 minutes and strain.","For the tare, simmer soy sauce, mirin, sake, and sugar for 1–2 minutes. Divide the tare and sesame oil between two warmed ramen bowls.","Heat the finished broth until very hot and prepare toppings before cooking the noodles; ramen should be assembled immediately.","Boil fresh ramen noodles according to the package, usually 1–3 minutes. Stir to separate, then drain extremely well.","Pour hot broth into each bowl and stir with the tare. Add noodles, lifting once to loosen them.","Top with egg, chashu, scallion, nori, and menma. Serve at once."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","egg"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Shoyu Ramen 醤油ラーメン Japanese food","Shoyu Ramen Japanese food"]},{"id":"jp_012","title":"Miso Ramen","japaneseName":"味噌ラーメン","romanization":"miso ramen","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":35,"total":55,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan and noodle pot","ingredients":["2 portions fresh ramen noodles","700 ml chicken or pork stock","3 tbsp red or awase miso","1 tbsp soy sauce","1 tbsp sake","1 tsp sugar","1 tsp grated ginger","1 clove garlic, grated","150 g ground pork","1 tsp sesame oil","100 g bean sprouts","80 g corn kernels","2 tbsp sliced scallion","2 soft-boiled eggs, optional"],"steps":["Mix miso, soy sauce, sake, sugar, ginger, and garlic into a smooth seasoning paste.","Heat sesame oil in a saucepan and cook the ground pork over medium-high heat until browned and fully cooked.","Add the seasoning paste and stir for about 30 seconds, then gradually add stock while stirring so the miso disperses evenly.","Do not boil hard for a long time after adding miso.","Add bean sprouts and corn and simmer just until hot and crisp-tender. Keep the soup very hot.","Cook ramen noodles separately according to package directions and drain well.","Divide noodles between bowls, ladle over the miso broth and pork, then top with scallion and egg if using."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","sesame","egg"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Miso Ramen 味噌ラーメン Japanese food","Miso Ramen Japanese food"]},{"id":"jp_013","title":"Tonkotsu Ramen","japaneseName":"豚骨ラーメン","romanization":"tonkotsu ramen","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":45,"cook":360,"total":405,"servings":4,"difficulty":"Hard","energy":"high","cleanup":3,"freezer":"no","equipment":"large stockpot","ingredients":["1.5 kg pork femur and neck bones","3 L water, plus more for blanching","1 onion, halved","1 head garlic, halved","30 g ginger, sliced","4 portions thin ramen noodles","4 tbsp soy sauce","2 tbsp mirin","1 tbsp sake","1 tsp salt, plus more to taste","8 slices chashu","4 ramen eggs","4 tbsp sliced scallion","pickled ginger and sesame seeds, optional"],"steps":["Rinse the bones, cover with cold water, bring to a hard boil for 10 minutes, then drain. Scrub away dark blood or scum from the bones and wash the pot; this keeps the broth cleaner-tasting.","Return the cleaned bones to the pot with 3 L fresh water.","Bring to a vigorous boil and maintain an active boil for about 5–6 hours, topping up with hot water as needed to keep the bones mostly submerged.","After the first hour, add onion, garlic, and ginger. Stir and break up the bones occasionally; agitation helps emulsify fat and collagen into the characteristic opaque broth.","Strain the broth through a sturdy fine sieve. Skim only excess surface fat, then season lightly with salt.","Make a simple shoyu tare by simmering soy sauce, mirin, and sake for 1–2 minutes.","Put about 1 tablespoon tare in each warmed bowl.","Cook thin ramen noodles just until firm, drain thoroughly, and add to bowls. Ladle in boiling-hot tonkotsu broth, then add chashu, ramen egg, scallion, pickled ginger, and sesame."],"notes":"Traditional tonkotsu broth is a long, vigorous pork-bone boil. This home version preserves that technique; use good ventilation and maintain food-safe handling of the bones.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","egg","sesame"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Tonkotsu Ramen 豚骨ラーメン Japanese food","Tonkotsu Ramen Japanese food"]},{"id":"jp_014","title":"Kitsune Udon","japaneseName":"きつねうどん","romanization":"kitsune udon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":20,"total":35,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"2 saucepans","ingredients":["2 portions udon noodles","700 ml dashi","2 tbsp light soy sauce or regular soy sauce","2 tbsp mirin","1/2 tsp salt","2 pieces aburaage fried tofu","150 ml dashi for tofu","1 tbsp soy sauce for tofu","1 tbsp sugar for tofu","1 tbsp mirin for tofu","2 tbsp sliced scallion"],"steps":["Blanch the aburaage in boiling water for 1 minute to remove excess surface oil, then gently squeeze dry.","Simmer the aburaage with 150 ml dashi, soy sauce, sugar, and mirin for 8–10 minutes until the liquid is mostly absorbed. Set aside.","For the udon broth, heat 700 ml dashi with soy sauce, mirin, and salt. Keep at a gentle simmer and adjust seasoning to a clean, savory balance.","Cook or warm the udon according to package directions. Drain well.","Divide noodles between bowls and pour over the hot broth.","Top each bowl with seasoned aburaage and scallion. Serve immediately."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Kitsune Udon きつねうどん Japanese food","Kitsune Udon Japanese food"]},{"id":"jp_015","title":"Curry Udon","japaneseName":"カレーうどん","romanization":"kare udon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":25,"total":40,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan","ingredients":["2 portions udon noodles","150 g thinly sliced pork or beef","1/2 onion, sliced","700 ml dashi","2 tbsp soy sauce","2 tbsp mirin","2 blocks Japanese curry roux, about 40 g","1 tbsp potato starch mixed with 1 tbsp water, optional","2 tbsp sliced scallion"],"steps":["Bring dashi, soy sauce, and mirin to a simmer. Add onion and cook for 4–5 minutes until softened.","Add the thinly sliced meat and simmer gently until fully cooked, skimming any foam.","Turn the heat low. Add curry roux a little at a time, stirring until completely dissolved. Do not add roux to a violently boiling pot.","If you want a thicker noodle broth, stir in the potato-starch slurry and simmer for 30–60 seconds until glossy.","Cook or warm udon separately, drain, and divide between bowls.","Ladle the curry broth and meat over the udon, finish with scallion, and serve very hot."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Curry Udon カレーうどん Japanese food","Curry Udon Japanese food"]},{"id":"jp_016","title":"Nabeyaki Udon","japaneseName":"鍋焼きうどん","romanization":"nabeyaki udon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":25,"total":45,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"2 small heatproof pots","ingredients":["2 portions udon noodles","800 ml dashi","2 tbsp soy sauce","2 tbsp mirin","1 tsp salt","150 g chicken thigh, bite-size pieces","4 shiitake mushrooms","4 slices kamaboko fish cake","2 eggs","2 shrimp tempura, optional","2 tbsp sliced scallion","handful of spinach, blanched"],"steps":["Prepare all toppings before cooking because nabeyaki udon is assembled quickly in individual pots.","Heat dashi with soy sauce, mirin, and salt. Add chicken and shiitake and simmer 5–7 minutes until the chicken is cooked through.","Divide the broth, chicken, and mushrooms between two small heatproof pots. Add udon and bring each pot back to a gentle simmer.","Arrange kamaboko and spinach around the noodles.","Crack one egg into each pot without breaking the yolk.","Cover and simmer 2–4 minutes depending on how set you prefer the egg. Use pasteurized eggs if serving the yolk very soft.","Add shrimp tempura at the end so it keeps some crispness, scatter with scallion, and serve in the cooking pot with care."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","egg","fish","shellfish"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Nabeyaki Udon 鍋焼きうどん Japanese food","Nabeyaki Udon Japanese food"]},{"id":"jp_017","title":"Zaru Soba","japaneseName":"ざるそば","romanization":"zaru soba","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":10,"total":25,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan and noodle pot","ingredients":["200 g dried soba noodles","200 ml water","100 ml soy sauce","30 ml mirin","20 g sugar","15 g katsuobushi bonito flakes","1 small scallion, finely sliced","wasabi, to taste","1/2 sheet nori, shredded"],"steps":["Make the dipping sauce: boil water, sugar, mirin, and soy sauce briefly. Add bonito flakes, return just to a boil, turn off the heat, cool, then strain. Chill the sauce.","Bring a large pot of unsalted water to a rolling boil and cook soba according to the package, stirring gently so the strands do not stick.","Drain immediately and rinse thoroughly under cold running water, gently rubbing and swishing the noodles to remove surface starch.","Cool the noodles completely in cold water, then drain very well.","Arrange soba on a tray or plate and top with shredded nori. Divide chilled dipping sauce into small cups.","Serve with scallion and wasabi. Dip only a portion of the noodles into the sauce before eating."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Zaru Soba ざるそば Japanese food","Zaru Soba Japanese food"]},{"id":"jp_018","title":"Yakisoba","japaneseName":"焼きそば","romanization":"yakisoba","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":15,"total":30,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"large skillet or griddle","ingredients":["2 portions steamed yakisoba noodles","150 g thinly sliced pork belly","120 g cabbage, chopped","1/2 carrot, thinly sliced","1/2 onion, sliced","1 tbsp neutral oil","2 tbsp Japanese Worcestershire-style sauce","1 tbsp oyster sauce","1 tsp soy sauce","aonori and pickled ginger, optional"],"steps":["Loosen the noodles according to package directions. If tightly packed, rinse briefly with warm water and drain thoroughly.","Heat oil in a large skillet or griddle over medium-high heat. Cook pork until nearly done and lightly browned.","Add onion and carrot and stir-fry 2 minutes, then add cabbage and cook until just tender but still crisp.","Add noodles. Let them contact the hot pan for 30–60 seconds before tossing so they pick up light browning.","Add Worcestershire-style sauce, oyster sauce, and soy sauce around the edge of the pan. Toss until the noodles are evenly seasoned and the pork is fully cooked.","Serve immediately with aonori and pickled ginger if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","shellfish"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Yakisoba 焼きそば Japanese food","Yakisoba Japanese food"]},{"id":"jp_019","title":"Yaki Udon","japaneseName":"焼きうどん","romanization":"yaki udon","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":15,"total":30,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"large skillet","ingredients":["2 portions udon noodles","150 g thinly sliced pork","120 g cabbage, chopped","1/2 onion, sliced","1/2 carrot, thinly sliced","1 tbsp neutral oil","1 1/2 tbsp soy sauce","1 tbsp mirin","1 tsp Worcestershire sauce","2 tbsp katsuobushi, optional","2 tbsp sliced scallion"],"steps":["Cook or loosen udon according to package instructions, then drain very well.","Heat oil in a large skillet over medium-high heat. Cook pork until almost done.","Add onion and carrot and stir-fry 2 minutes, then add cabbage and cook another 1–2 minutes.","Add drained udon and toss gently so the noodles do not break. Let them sear briefly where they contact the pan.","Add soy sauce, mirin, and Worcestershire sauce; toss until evenly coated and the pork is fully cooked.","Finish with scallion and katsuobushi if using. Serve hot."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Yaki Udon 焼きうどん Japanese food","Yaki Udon Japanese food"]},{"id":"jp_020","title":"Hiyashi Chuka","japaneseName":"冷やし中華","romanization":"hiyashi chuka","category":"Noodles","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":10,"total":35,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet and noodle pot","ingredients":["2 portions fresh ramen noodles","2 eggs","1 tsp neutral oil","1/2 cucumber, julienned","1 small tomato, cut into wedges","80 g ham, julienned","60 g cooked shrimp, optional","3 tbsp soy sauce","3 tbsp rice vinegar","2 tbsp sugar","1 tbsp sesame oil","2 tbsp water","1 tsp grated ginger"],"steps":["Whisk the eggs. Cook as a thin omelet in a lightly oiled skillet, cool, then slice into fine strips.","Prepare cucumber, tomato, ham, and shrimp and keep chilled.","Whisk soy sauce, rice vinegar, sugar, sesame oil, water, and ginger until the sugar dissolves. Chill the dressing.","Boil ramen noodles according to package directions. Drain and rinse thoroughly under cold water until completely cool, then drain very well.","Divide noodles between shallow bowls. Arrange the toppings in neat sections over the noodles.","Spoon the chilled dressing over just before serving and toss at the table."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","egg","sesame","shellfish"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Hiyashi Chuka 冷やし中華 Japanese food","Hiyashi Chuka Japanese food"]},{"id":"jp_021","title":"Chicken Teriyaki","japaneseName":"鶏の照り焼き","romanization":"tori no teriyaki","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":18,"total":28,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet","ingredients":["2 boneless skin-on chicken thighs, about 300 g total","1 tsp neutral oil","2 tbsp soy sauce","2 tbsp mirin","2 tbsp sake","1 tbsp sugar"],"steps":["Pat the chicken dry and trim excess fat. Prick the skin in several places so it renders evenly.","Mix soy sauce, mirin, sake, and sugar until the sugar starts to dissolve.","Heat oil in a skillet over medium heat. Place chicken skin-side down and press lightly for the first minute. Cook 5–7 minutes until deeply golden, spooning off excess rendered fat.","Turn the chicken and cook 3–5 minutes until almost cooked through.","Lower the heat, add the teriyaki mixture, and simmer while turning the chicken repeatedly until the sauce becomes glossy and coats the meat.","Rest 2 minutes, slice, and spoon the remaining glaze over the chicken."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Chicken Teriyaki 鶏の照り焼き Japanese food","Chicken Teriyaki Japanese food"]},{"id":"jp_022","title":"Chicken Karaage","japaneseName":"鶏の唐揚げ","romanization":"tori no karaage","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":15,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep pot or fryer","ingredients":["600 g boneless chicken thighs, bite-size pieces","2 tbsp soy sauce","1 tbsp sake","1 tbsp grated ginger","1 clove garlic, grated","70 g potato starch","30 g all-purpose flour","neutral oil for deep-frying, as needed","4 lemon wedges"],"steps":["Mix chicken with soy sauce, sake, ginger, and garlic. Marinate 20–30 minutes in the refrigerator, then drain off excess liquid.","Combine potato starch and flour. Coat each chicken piece thoroughly just before frying, pressing the starch into moist crevices.","Heat oil to about 170°C. Fry in batches for 3–4 minutes until pale golden and cooked almost through. Do not crowd the pot.","Transfer to a rack and rest 3 minutes; this pause lets residual heat move through the meat.","Increase the oil to about 185°C and fry the chicken a second time for 45–75 seconds until crisp and deep golden.","Drain on a rack, season lightly if needed, and serve hot with lemon."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Chicken Karaage 鶏の唐揚げ Japanese food","Chicken Karaage Japanese food"]},{"id":"jp_023","title":"Chicken Nanban","japaneseName":"チキン南蛮","romanization":"chikin nanban","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet and small saucepan","ingredients":["2 boneless chicken thighs, about 320 g","1/2 tsp salt and 1/4 tsp black pepper","3 tbsp all-purpose flour","1 egg, beaten","neutral oil for shallow-frying, as needed","2 tbsp soy sauce","2 tbsp rice vinegar","2 tbsp sugar","1 tbsp mirin","2 hard-boiled eggs, chopped","3 tbsp Japanese mayonnaise","1 tbsp finely chopped onion","1 tbsp chopped pickles or cucumber","1 tsp lemon juice"],"steps":["Make the tartar sauce by mixing chopped egg, mayonnaise, onion, pickle, and lemon.","Chill while you cook the chicken.","Combine soy sauce, rice vinegar, sugar, and mirin in a small pan and warm just until the sugar dissolves; keep the nanban sauce warm.","Season chicken lightly, coat with flour, then dip in beaten egg.","Shallow-fry over medium heat until golden on both sides and fully cooked, about 5–7 minutes per side depending on thickness.","While the chicken is still hot, place it in the warm nanban sauce and turn several times so the coating absorbs the sweet-sour seasoning.","Slice and serve with plenty of tartar sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Chicken Nanban チキン南蛮 Japanese food","Chicken Nanban Japanese food"]},{"id":"jp_024","title":"Tonkatsu","japaneseName":"豚カツ","romanization":"tonkatsu","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":15,"total":35,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep frying pot","ingredients":["2 pork loin cutlets, about 140 g each","1/2 tsp salt and 1/4 tsp black pepper","3 tbsp all-purpose flour","1 egg, beaten","70 g panko breadcrumbs","neutral oil for deep-frying, as needed","120 g finely shredded cabbage","tonkatsu sauce, to serve"],"steps":["Cut small slits through the fat and connective tissue around the edge of each pork cutlet to reduce curling. Pound to an even thickness and season lightly.","Coat each cutlet in flour and shake off excess, dip in beaten egg, then press into panko without crushing the crumbs.","Heat oil to about 170°C. Lower in the cutlets carefully and fry until golden on the first side.","Turn once and continue frying until the center is safely cooked, usually 5–7 minutes total depending on thickness.","Drain upright on a rack and rest 3–5 minutes before slicing; resting helps keep the juices in the meat.","Slice into strips and serve with shredded cabbage and tonkatsu sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Tonkatsu 豚カツ Japanese food","Tonkatsu Japanese food"]},{"id":"jp_025","title":"Shogayaki","japaneseName":"豚の生姜焼き","romanization":"buta no shogayaki","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":12,"total":27,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet","ingredients":["300 g thinly sliced pork loin","1/2 onion, thinly sliced","1 tbsp neutral oil","2 tbsp soy sauce","2 tbsp sake","1 tbsp mirin","1 tbsp grated fresh ginger","1 tsp sugar","shredded cabbage, to serve"],"steps":["Mix soy sauce, sake, mirin, ginger, and sugar. Keep the pork slices loose rather than marinating them for a long time.","Heat oil in a skillet over medium-high heat. Cook the pork in batches for about 1 minute per side until lightly browned; remove before it dries out.","Add onion to the same pan and cook 2–3 minutes until softened.","Return pork to the pan and add the ginger sauce. Toss over medium heat for 1–2 minutes until the sauce reduces and coats the meat.","Check that the pork is fully cooked, then remove from heat immediately.","Serve with shredded cabbage and hot rice."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Shogayaki 豚の生姜焼き Japanese food","Shogayaki Japanese food"]},{"id":"jp_026","title":"Nikujaga","japaneseName":"肉じゃが","romanization":"nikujaga","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":35,"total":55,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"wide pot","ingredients":["350 g thinly sliced beef or pork","600 g potatoes, peeled and cut into large chunks","1 onion, cut into wedges","1 carrot, cut into chunks","150 g shirataki noodles, rinsed and cut, optional","250 ml dashi","3 tbsp soy sauce","3 tbsp mirin","2 tbsp sake","2 tbsp sugar","1 tbsp neutral oil","80 g green beans, blanched"],"steps":["Rinse the shirataki well and briefly boil if the package recommends it.","Prepare potatoes, carrot, and onion in large pieces so they hold their shape.","Heat oil in a wide pot. Cook the meat briefly until most of the pink disappears, then add onion and carrot and stir for 2 minutes.","Add potatoes and shirataki. Pour in dashi, sugar, sake, and mirin and bring to a gentle boil.","Skim foam, then cover with a drop lid or parchment circle and simmer 12–15 minutes until the vegetables are nearly tender.","Add soy sauce and continue simmering uncovered or with the drop lid until potatoes are tender and the broth has reduced, about 8–10 minutes.","Rest 10 minutes off the heat so the flavors absorb, then rewarm gently and garnish with green beans."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Nikujaga 肉じゃが Japanese food","Nikujaga Japanese food"]},{"id":"jp_027","title":"Hambagu","japaneseName":"ハンバーグ","romanization":"hanbagu","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet","ingredients":["350 g ground beef","150 g ground pork","1 small onion, finely diced","1 tsp neutral oil","40 g panko","60 ml milk","1 egg","1/2 tsp salt","1/4 tsp black pepper","1 tbsp neutral oil for frying","3 tbsp ketchup","2 tbsp Worcestershire sauce","2 tbsp water","1 tsp butter"],"steps":["Cook the diced onion in 1 teaspoon oil over medium-low heat until translucent. Cool completely. Soak panko in milk for 5 minutes.","Mix beef, pork, cooled onion, soaked panko, egg, salt, and pepper. Knead just until sticky and cohesive; overmixing can make the patties dense.","Divide into four. Toss each portion between your hands to expel large air pockets, shape into oval patties, and press a shallow indentation in the center.","Heat oil in a skillet over medium heat. Brown patties 3–4 minutes on the first side, turn, add 2 tablespoons water, cover, and cook 6–8 minutes until safely cooked through.","Remove patties. Add ketchup, Worcestershire sauce, 2 tablespoons water, and butter to the pan; scrape up browned bits and simmer to a glossy sauce.","Serve the hambagu with the pan sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","milk"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Hambagu ハンバーグ Japanese food","Hambagu Japanese food"]},{"id":"jp_028","title":"Buta no Kakuni","japaneseName":"豚の角煮","romanization":"buta no kakuni","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":130,"total":150,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"heavy pot","ingredients":["800 g pork belly, cut into 5 cm cubes","30 g ginger, sliced","2 scallions, green parts reserved","700 ml water","100 ml sake","4 tbsp soy sauce","3 tbsp sugar","3 tbsp mirin","4 soft- or hard-boiled eggs, optional","blanched mustard greens, optional"],"steps":["Brown the pork belly cubes in a heavy pot over medium heat, starting fatty side down. Drain excess rendered fat.","Cover pork with fresh water, add half the ginger and scallion greens, and simmer gently for 60 minutes.","Drain and rinse the pork; discard the blanching liquid.","Return pork to the clean pot with 700 ml water, sake, remaining ginger, and sugar. Simmer gently 30 minutes.","Add soy sauce and mirin. Cover with a drop lid and simmer another 30–40 minutes until the pork is very tender.","If using cooked eggs, add them during the final 15 minutes and turn occasionally so they color evenly.","Let the pork rest in the braising liquid for at least 15 minutes; skim excess fat, rewarm gently, and serve with some reduced sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","egg"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Buta no Kakuni 豚の角煮 Japanese food","Buta no Kakuni Japanese food"]},{"id":"jp_029","title":"Saba no Misoni","japaneseName":"鯖の味噌煮","romanization":"saba no misoni","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":20,"total":35,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"wide saucepan","ingredients":["2 mackerel fillets, about 150 g each","150 ml water","50 ml sake","2 tbsp mirin","1 tbsp sugar","2 tbsp miso","1 tbsp soy sauce","15 g ginger, thinly sliced"],"steps":["Check the mackerel for pin bones and cut each fillet in half. Make a shallow cross cut in the skin of thick pieces.","Pour boiling water briefly over the fish, then immediately rinse in cool water. This traditional pre-treatment helps remove surface odor and blood.","Bring water, sake, mirin, sugar, and ginger to a simmer in a wide pan. Add mackerel skin-side up.","Cover with a drop lid and simmer gently for about 8 minutes.","Dissolve miso with a little hot cooking liquid, then add it with soy sauce. Continue simmering 5–7 minutes, spooning sauce over the fish without breaking it.","When the fish is cooked and the sauce lightly thickened, rest for 2 minutes and serve with ginger and sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Saba no Misoni 鯖の味噌煮 Japanese food","Saba no Misoni Japanese food"]},{"id":"jp_030","title":"Salmon Shioyaki","japaneseName":"鮭の塩焼き","romanization":"sake no shioyaki","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":35,"cook":12,"total":47,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"grill, broiler, or grill pan","ingredients":["2 skin-on salmon fillets, 150–180 g each","1 tsp fine salt","grated daikon, optional","2 lemon or sudachi wedges"],"steps":["Pat salmon dry. Sprinkle salt evenly over both sides and refrigerate uncovered for 30 minutes; this seasons the fish and draws out surface moisture.","Pat the salmon dry again. Bring close to room temperature while preheating a grill, broiler, or grill pan.","Cook skin-side toward the stronger heat first until the skin is crisp and the fish is mostly opaque, about 5–7 minutes depending on thickness.","Turn and cook the second side just until the center is safely cooked and still moist, about 3–5 minutes.","Rest 2 minutes. Serve with grated daikon and citrus if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Salmon Shioyaki 鮭の塩焼き Japanese food","Salmon Shioyaki Japanese food"]},{"id":"jp_031","title":"Saikyo Yaki Cod","japaneseName":"西京焼き","romanization":"saikyo yaki","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":12,"total":500,"servings":2,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"broiler or grill","ingredients":["2 cod or sablefish fillets, 150 g each","80 g white miso","2 tbsp mirin","2 tbsp sake","1 tbsp sugar"],"steps":["Mix white miso, mirin, sake, and sugar into a smooth marinade.","Pat the fish dry and coat all sides with the miso mixture. Refrigerate 6–8 hours; for delicate cod, avoid excessively long marination because salt can firm the flesh too much.","Remove fish from the marinade and wipe off most of the miso with your fingers or a damp paper towel; thick miso burns before the fish cooks.","Broil or grill over medium heat, starting skin-side down if present, until lightly caramelized.","Turn once if needed and cook until the center is opaque and flakes easily, about 8–12 minutes total depending on thickness.","Rest 2 minutes before serving."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Saikyo Yaki Cod 西京焼き Japanese food","Saikyo Yaki Cod Japanese food"]},{"id":"jp_032","title":"Japanese Beef Curry","japaneseName":"ビーフカレー","romanization":"biifu karee","category":"Main Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":60,"total":80,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"heavy pot","ingredients":["500 g beef chuck, 3 cm cubes","1 large onion, sliced","2 carrots, large chunks","2 potatoes, large chunks","1 tbsp neutral oil","800 ml water or unsalted stock","100 g Japanese curry roux blocks","1 tsp grated apple or honey, optional","cooked Japanese rice, to serve"],"steps":["Pat beef dry. Heat oil in a heavy pot and brown the beef in batches; do not crowd the pot.","Add onion and cook 6–8 minutes until soft and lightly golden. Return all beef to the pot.","Add water or stock, bring to a boil, skim foam, then lower to a gentle simmer and cook 30 minutes.","Add carrots and potatoes and simmer 15–20 minutes until the beef and vegetables are tender.","Turn off the heat.","Break curry roux into pieces and dissolve them one at a time, stirring until smooth. Add grated apple or honey if using.","Return to low heat and simmer 5–10 minutes, stirring frequently so the thick curry does not catch. Serve beside hot rice."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","milk"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Japanese Beef Curry ビーフカレー Japanese food","Japanese Beef Curry Japanese food"]},{"id":"jp_033","title":"Assorted Tempura","japaneseName":"天ぷら","romanization":"tempura","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":20,"total":45,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep pot or fryer","ingredients":["6 medium shrimp","1 small Japanese eggplant","80 g kabocha squash","4 shiitake mushrooms","4 green beans","100 g all-purpose flour, plus extra for dusting","1 egg","200 ml ice-cold water","neutral oil for deep-frying, as needed","150 ml dashi","2 tbsp soy sauce","2 tbsp mirin","grated daikon and ginger, optional"],"steps":["Make tentsuyu by simmering dashi, soy sauce, and mirin for 2–3 minutes. Keep warm.","Prepare and thoroughly dry the shrimp and vegetables.","Make shallow cuts under the shrimp and gently straighten them; cut vegetables into pieces thin enough to cook quickly.","Heat oil to about 170°C. Keep batter ingredients cold until the last moment.","Beat egg into ice-cold water. Add flour and mix only a few strokes with chopsticks or a fork; leave visible lumps and do not develop gluten.","Dust ingredients lightly with flour, dip in batter, and fry in small batches. Vegetables generally take 2–3 minutes; shrimp about 2–3 minutes depending on size.","Drain on a rack and serve immediately with tentsuyu, grated daikon, and ginger."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","shellfish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Assorted Tempura 天ぷら Japanese food","Assorted Tempura Japanese food"]},{"id":"jp_034","title":"Osaka-Style Okonomiyaki","japaneseName":"お好み焼き","romanization":"okonomiyaki","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":20,"total":40,"servings":2,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"griddle or large skillet","ingredients":["120 g all-purpose flour","160 ml dashi","2 eggs","300 g cabbage, finely chopped","2 tbsp tenkasu tempura crumbs, optional","2 tbsp pickled red ginger, chopped","120 g thinly sliced pork belly","1 tbsp neutral oil","4 tbsp okonomiyaki sauce","2 tbsp Japanese mayonnaise","1 tsp aonori and 5 g katsuobushi"],"steps":["Whisk flour and dashi until just smooth. Stir in eggs, then fold in cabbage, tenkasu, and pickled ginger. Do not compress the cabbage.","Heat a lightly oiled griddle or skillet over medium heat. Divide the batter into two thick rounds about 15 cm wide.","Lay pork belly slices over the top of each pancake. Cook 4–5 minutes until the bottom is browned and stable enough to flip.","Flip carefully so the pork is now underneath.","Cook another 5–6 minutes, pressing only very lightly; excessive pressing makes the pancake dense.","Flip once more and cook 1–2 minutes until the center is fully set and the pork is cooked.","Brush with okonomiyaki sauce, drizzle mayonnaise, and finish with aonori and katsuobushi."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","soy","fish"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Osaka-Style Okonomiyaki お好み焼き Japanese food","Osaka-Style Okonomiyaki Japanese food"]},{"id":"jp_035","title":"Takoyaki","japaneseName":"たこ焼き","romanization":"takoyaki","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"takoyaki pan","ingredients":["120 g all-purpose flour","400 ml dashi","2 eggs","1 tbsp soy sauce","150 g cooked octopus, 1.5 cm pieces","3 tbsp tenkasu","2 tbsp pickled red ginger, chopped","2 tbsp sliced scallion","1 tbsp neutral oil for the pan, plus more as needed","4 tbsp takoyaki sauce","2 tbsp Japanese mayonnaise","1 tsp aonori and 5 g katsuobushi"],"steps":["Whisk flour, dashi, eggs, and soy sauce into a thin batter. Transfer to a jug for easier pouring.","Heat a takoyaki pan over medium-high heat and oil every cavity generously, including the flat surface between holes.","Fill cavities nearly to the top with batter.","Add octopus, tenkasu, ginger, and scallion, then pour a little more batter so it spills slightly over the edges.","When the edges set, use skewers to cut the connecting batter and rotate each ball about 90 degrees, tucking loose batter underneath.","Continue turning repeatedly until the takoyaki are round, crisp outside, and cooked through, about 6–8 minutes total.","Transfer to a plate and finish with takoyaki sauce, mayonnaise, aonori, and katsuobushi."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","soy","mollusk","fish"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Takoyaki たこ焼き Japanese food","Takoyaki Japanese food"]},{"id":"jp_036","title":"Yakitori","japaneseName":"焼き鳥","romanization":"yakitori","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":15,"total":40,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"grill or grill pan","ingredients":["600 g boneless chicken thigh","4 scallions, white and light-green parts","8 bamboo skewers, soaked","60 ml soy sauce","60 ml mirin","30 ml sake","1 1/2 tbsp sugar"],"steps":["Soak bamboo skewers in water for at least 20 minutes. Cut chicken into 2.5 cm pieces and scallion into 3 cm lengths.","Make tare by simmering soy sauce, mirin, sake, and sugar for 5–7 minutes until lightly syrupy. Reserve some clean sauce for serving.","Thread chicken and scallion alternately onto skewers without packing too tightly.","Grill over medium-high heat, turning every 1–2 minutes, until the chicken is nearly cooked and lightly charred.","Brush with tare during the final several turns, allowing each layer to caramelize before adding more.","Cook chicken fully, then brush with reserved clean tare and serve immediately."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Yakitori 焼き鳥 Japanese food","Yakitori Japanese food"]},{"id":"jp_037","title":"Japanese Gyoza","japaneseName":"餃子","romanization":"gyoza","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":15,"total":45,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"nonstick skillet","ingredients":["30 gyoza wrappers","300 g ground pork","200 g napa cabbage, finely chopped","1/2 tsp salt for cabbage","3 scallions, finely chopped","1 tbsp grated ginger","1 clove garlic, grated","1 tbsp soy sauce","1 tbsp sake","1 tsp sesame oil","1 tsp potato starch","1 tbsp neutral oil","80 ml water","2 tbsp rice vinegar plus 2 tbsp soy sauce, for dipping"],"steps":["Salt the chopped cabbage, rest 10 minutes, then squeeze out as much water as possible.","Mix pork, cabbage, scallion, ginger, garlic, soy sauce, sake, sesame oil, and potato starch until the filling becomes slightly sticky.","Place about 1 tablespoon filling in each wrapper.","Moisten the rim, fold, and pleat one side against the other; keep finished gyoza covered so wrappers do not dry.","Heat oil in a nonstick skillet. Arrange gyoza flat-side down and cook 1–2 minutes until the bottoms begin to color.","Add water, immediately cover, and steam 4–5 minutes until the filling is fully cooked.","Remove the lid and cook until the water evaporates and bottoms become crisp. Serve hot with vinegar-soy dipping sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["gluten","soy","sesame"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Japanese Gyoza 餃子 Japanese food","Japanese Gyoza Japanese food"]},{"id":"jp_038","title":"Korokke","japaneseName":"コロッケ","romanization":"korokke","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":35,"cook":20,"total":55,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"pot and deep fryer","ingredients":["700 g potatoes, peeled and quartered","200 g ground beef","1 small onion, finely diced","1 tsp neutral oil","1 tsp sugar","1 tbsp soy sauce","1/2 tsp salt and 1/4 tsp black pepper","60 g all-purpose flour","2 eggs, beaten","120 g panko","neutral oil for deep-frying, as needed"],"steps":["Boil potatoes in salted water until very tender. Drain thoroughly, return to the hot pot for 1 minute to steam off moisture, then mash while hot.","Cook onion in oil until soft. Add beef and cook until fully browned; season with sugar, soy sauce, salt, and pepper. Cook until excess moisture is gone.","Mix beef mixture into the mashed potatoes. Spread on a tray and cool until firm enough to handle.","Shape into 8 oval patties. Coat each in flour, beaten egg, then panko. Chill 15 minutes if the coating feels soft.","Heat oil to about 175°C. Fry in batches until crisp and golden, usually 2–3 minutes because the filling is already cooked.","Drain on a rack and serve with tonkatsu-style sauce or plain."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Korokke コロッケ Japanese food","Korokke Japanese food"]},{"id":"jp_039","title":"Menchi Katsu","japaneseName":"メンチカツ","romanization":"menchi katsu","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":20,"total":50,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep fryer or heavy pot","ingredients":["300 g ground beef","200 g ground pork","1 small onion, finely diced","1 tsp neutral oil","40 g panko","60 ml milk","1 egg","1 tsp salt","1/4 tsp black pepper","50 g all-purpose flour","2 eggs, beaten, for coating","120 g panko for coating","neutral oil for deep-frying, as needed"],"steps":["Cook onion in 1 teaspoon oil until soft and translucent, then cool completely. Soak 40 g panko in milk.","Mix beef, pork, onion, soaked panko, egg, salt, and pepper until cohesive. Divide into six thick oval patties and chill 15 minutes.","Coat patties in flour, then beaten egg, then panko. Press gently so the crumb layer adheres.","Heat frying oil to about 170°C. Fry in batches, turning once, until deep golden and the center is fully cooked, about 6–8 minutes depending on thickness.","Drain on a rack and rest 3 minutes before serving.","Serve with shredded cabbage and tonkatsu sauce if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","milk"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Menchi Katsu メンチカツ Japanese food","Menchi Katsu Japanese food"]},{"id":"jp_040","title":"Ebi Fry","japaneseName":"エビフライ","romanization":"ebi furai","category":"Fried & Street Food","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":15,"total":40,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"deep fryer or heavy pot","ingredients":["12 large shrimp","1/2 tsp salt and 1/4 tsp black pepper","50 g all-purpose flour","2 eggs, beaten","120 g panko","neutral oil for deep-frying, as needed","4 lemon wedges","tartar sauce, optional"],"steps":["Peel and devein shrimp, leaving tails on if desired. Make several shallow cuts on the underside, then gently straighten so they fry without curling tightly.","Pat very dry and season lightly. Coat each shrimp in flour, then beaten egg, then panko.","Heat oil to about 175°C. Fry shrimp in batches for about 2–3 minutes until golden and just cooked through.","Drain on a rack; do not pile hot fried shrimp because trapped steam softens the crust.","Serve immediately with lemon and tartar sauce."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["shellfish","egg","gluten"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Ebi Fry エビフライ Japanese food","Ebi Fry Japanese food"]},{"id":"jp_041","title":"Miso Soup with Tofu and Wakame","japaneseName":"豆腐とわかめの味噌汁","romanization":"tofu to wakame no misoshiru","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":10,"total":20,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan","ingredients":["800 ml dashi","150 g silken or soft tofu, 2 cm cubes","2 tbsp dried wakame, rehydrated","3–4 tbsp miso, to taste","2 scallions, thinly sliced"],"steps":["Bring dashi to a gentle simmer. Add tofu and warm for 1–2 minutes without vigorous boiling.","Add rehydrated wakame and heat briefly.","Place miso in a ladle or small bowl, add some hot dashi, and stir until smooth.","Lower the heat or turn it off, then dissolve the thinned miso back into the soup. Avoid prolonged boiling after adding miso.","Taste and add a little more miso if needed.","Serve immediately with sliced scallion."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","fish"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Miso Soup with Tofu and Wakame 豆腐とわかめの味噌汁 Japanese food","Miso Soup with Tofu and Wakame Japanese food"]},{"id":"jp_042","title":"Tonjiru","japaneseName":"豚汁","romanization":"tonjiru","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":30,"total":50,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"soup pot","ingredients":["200 g thinly sliced pork belly","1 tbsp neutral oil","1/2 daikon, about 250 g, half-moons","1 carrot, half-moons","150 g potato or satoimo, chunks","100 g gobo, shaved and rinsed","100 g konnyaku, torn into pieces","900 ml dashi","4 tbsp miso","2 scallions, sliced"],"steps":["Prepare vegetables in bite-size pieces. Briefly blanch konnyaku if strongly scented and drain.","Heat oil in a soup pot and cook pork until it loses most of its pink color.","Add daikon, carrot, potato, gobo, and konnyaku and stir for 2 minutes.","Add dashi, bring to a boil, skim foam, then simmer 15–20 minutes until the root vegetables are tender.","Turn the heat low. Dissolve miso with a little broth, then stir it back into the soup without prolonged boiling.","Serve hot with sliced scallion."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","fish"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Tonjiru 豚汁 Japanese food","Tonjiru Japanese food"]},{"id":"jp_043","title":"Sukiyaki","japaneseName":"すき焼き","romanization":"sukiyaki","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":25,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"shallow hot pot","ingredients":["600 g very thinly sliced beef","1 block firm tofu, drained and cut","1 napa cabbage, about 500 g, chopped","200 g shiitake and enoki mushrooms","2 Japanese long onions or 4 scallions, large pieces","200 g shirataki noodles, rinsed","120 ml soy sauce","120 ml mirin","60 ml sake","3 tbsp sugar","4 pasteurized eggs, optional for dipping"],"steps":["Mix soy sauce, mirin, sake, and sugar for the warishita sauce. Prepare all ingredients and arrange them on platters before heating the pot.","Heat a shallow sukiyaki pot. Sear a few slices of beef briefly, sprinkle with a little sugar, then add a splash of warishita.","Move beef to the side and arrange tofu, cabbage, mushrooms, long onion, and shirataki around the pot. Add enough warishita to season without completely submerging everything.","Simmer gently, adding ingredients in batches as space opens. Avoid cooking thin beef for too long.","Adjust with a little water or dashi if the broth becomes too salty as it reduces.","Serve directly from the pot. If using raw egg as a dip, use eggs produced for raw consumption or pasteurized eggs; otherwise omit."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","egg"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Sukiyaki すき焼き Japanese food","Sukiyaki Japanese food"]},{"id":"jp_044","title":"Shabu-Shabu","japaneseName":"しゃぶしゃぶ","romanization":"shabu-shabu","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":20,"total":45,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"tabletop hot pot","ingredients":["600 g paper-thin sliced beef or pork","1 L water","15 g kombu","300 g napa cabbage","200 g tofu","200 g mixed mushrooms","1 long onion, diagonal slices","200 g udon noodles, optional finish","120 ml ponzu sauce, for dipping","120 ml sesame dipping sauce"],"steps":["Soak kombu in 1 L water for 20–30 minutes in the hot pot. Warm slowly and remove the kombu just before the water boils.","Arrange meat, vegetables, tofu, mushrooms, and dipping sauces at the table.","Add firmer vegetables and tofu to the gently simmering kombu broth first.","Each diner swishes a slice of meat through the hot broth until fully cooked, then dips it in ponzu or sesame sauce.","Continue adding vegetables in manageable batches and skim foam as needed. Keep the broth at a simmer rather than a violent boil.","After the main ingredients are eaten, cook udon in the flavorful remaining broth if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","sesame","gluten"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Shabu-Shabu しゃぶしゃぶ Japanese food","Shabu-Shabu Japanese food"]},{"id":"jp_045","title":"Oden","japaneseName":"おでん","romanization":"oden","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":80,"total":110,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"wide pot","ingredients":["1.5 L dashi","3 tbsp soy sauce","3 tbsp mirin","1 tsp salt","1/2 daikon, thick rounds","4 hard-boiled eggs","1 block konnyaku, cut into triangles","4 pieces chikuwa fish cake","4 pieces satsuma-age fish cake","1 block atsuage fried tofu, cut","mustard, to serve"],"steps":["Peel daikon rounds, round off sharp edges if desired, and simmer separately in water until partly tender.","Score konnyaku and blanch for 2 minutes.","Bring dashi, soy sauce, mirin, and salt to a gentle simmer in a wide pot.","Add daikon, eggs, and konnyaku first. Simmer very gently for about 30 minutes.","Blanch atsuage and fish cakes briefly with hot water to remove excess surface oil, then add them to the pot.","Continue simmering another 25–30 minutes. Turn off the heat and let the oden rest at least 20 minutes; cooling and reheating improves absorption.","Reheat gently without hard boiling and serve with Japanese mustard."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","fish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Oden おでん Japanese food","Oden Japanese food"]},{"id":"jp_046","title":"Chanko Nabe","japaneseName":"ちゃんこ鍋","romanization":"chanko nabe","category":"Soups & Hot Pots","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":30,"cook":30,"total":60,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"large hot pot","ingredients":["1.2 L dashi or chicken stock","3 tbsp soy sauce","2 tbsp mirin","2 tbsp sake","1 tsp salt","400 g ground chicken","1 egg","2 tbsp potato starch","1 tbsp grated ginger","400 g napa cabbage","200 g tofu","200 g mixed mushrooms","1 carrot, sliced","2 scallions, large pieces"],"steps":["Mix ground chicken, egg, potato starch, ginger, and a pinch of salt until sticky. Shape into small meatballs with damp hands or two spoons.","Bring dashi or stock, soy sauce, mirin, sake, and salt to a gentle simmer.","Add chicken meatballs and cook 5–6 minutes, skimming foam, until firm and cooked through.","Add carrot, cabbage stems, tofu, and mushrooms. Simmer until nearly tender.","Add cabbage leaves and scallions last and cook just until softened.","Serve from the pot. Noodles or rice can be added to the remaining broth after the main ingredients are eaten."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Chanko Nabe ちゃんこ鍋 Japanese food","Chanko Nabe Japanese food"]},{"id":"jp_047","title":"Nigiri Sushi","japaneseName":"握り寿司","romanization":"nigiri-zushi","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":40,"cook":20,"total":60,"servings":4,"difficulty":"Hard","energy":"high","cleanup":3,"freezer":"no","equipment":"sharp sashimi knife","ingredients":["600 g cooked Japanese short-grain rice","80 ml rice vinegar","35 g sugar","10 g salt","400 g assorted sashimi-grade fish, sliced into 20 pieces","wasabi, optional","soy sauce, to serve"],"steps":["While the rice is hot, combine rice vinegar, sugar, and salt until dissolved. Fold the seasoning through the rice with a slicing motion while fanning until glossy and just warm.","Keep sushi rice covered with a damp cloth at room temperature while working; do not refrigerate it before shaping because it hardens.","Use fish specifically sold for raw consumption and maintain an unbroken cold chain.","Slice across the grain into pieces large enough to drape over a rice mound.","Moisten your hands lightly with vinegared water. Shape about 25 g rice into a compact oval without crushing the grains.","Place a tiny amount of wasabi on the fish if desired, lay the fish over the rice, and gently press and shape the two together.","Serve promptly with soy sauce. Keep raw seafood chilled until assembly and discard any fish that has been held unsafely."],"notes":"Use only seafood intended for raw consumption. Raw seafood safety depends on species, freezing, handling, and local food regulations.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Nigiri Sushi 握り寿司 Japanese food","Nigiri Sushi Japanese food"]},{"id":"jp_048","title":"Maki Sushi","japaneseName":"巻き寿司","romanization":"maki-zushi","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":35,"cook":15,"total":50,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"bamboo sushi mat","ingredients":["500 g prepared sushi rice","4 sheets nori","1 cucumber, cut into long strips","100 g sashimi-grade tuna or cooked crab sticks","wasabi, optional","soy sauce, to serve"],"steps":["Prepare seasoned sushi rice and let it cool to body temperature. Keep it covered so the surface does not dry.","Lay a sheet of nori shiny-side down on a bamboo mat. With damp fingers, spread a thin, even layer of rice over about three-quarters of the sheet, leaving the far edge bare.","Arrange cucumber and tuna or cooked crab in a narrow line across the lower third. Avoid overfilling.","Lift the mat and roll firmly over the filling, then continue rolling while applying even pressure to form a cylinder.","Moisten the bare nori edge lightly and finish the roll seam-side down. Rest 2 minutes.","Use a sharp damp knife to cut each roll into 6–8 pieces, wiping the blade between cuts. Serve promptly."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Maki Sushi 巻き寿司 Japanese food","Maki Sushi Japanese food"]},{"id":"jp_049","title":"Futomaki","japaneseName":"太巻き","romanization":"futomaki","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":45,"cook":20,"total":65,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"bamboo sushi mat","ingredients":["600 g prepared sushi rice","4 full sheets nori","4 eggs","1 tbsp sugar","pinch of salt","1 cucumber, long strips","100 g seasoned shiitake mushrooms","100 g cooked spinach, squeezed dry","8 strips kanpyo, simmered until tender, optional","100 g cooked shrimp or imitation crab"],"steps":["Make a lightly sweet tamagoyaki with eggs, sugar, and salt; cool and cut into long strips.","Prepare all other fillings and remove excess moisture.","Place nori on a bamboo mat and spread sushi rice evenly, leaving a 2 cm border at the far edge.","Arrange several fillings in parallel lines across the lower third, balancing colors and textures rather than piling them in one spot.","Lift the mat over the fillings and tuck firmly, then roll forward in one steady motion while keeping the fillings centered.","Shape the finished roll with gentle pressure and let it rest seam-side down for 2 minutes.","Slice with a sharp damp knife into thick rounds and serve."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","fish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Futomaki 太巻き Japanese food","Futomaki Japanese food"]},{"id":"jp_050","title":"Temaki Sushi","japaneseName":"手巻き寿司","romanization":"temaki-zushi","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":35,"cook":10,"total":45,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"serving platters","ingredients":["600 g prepared sushi rice","8 sheets nori, halved","200 g sashimi-grade salmon or tuna, strips","1 cucumber, thin sticks","100 g tamagoyaki, cut into strips","100 g cooked shrimp or crab, optional","shiso leaves, optional","wasabi to taste and 60 ml soy sauce, for serving"],"steps":["Prepare seasoned sushi rice and all fillings before serving. Keep raw fish chilled until it reaches the table.","Cut nori sheets in half. Put one piece in your dry hand with the rough side facing up.","Spread a small amount of rice over the left half in a thin layer, leaving edges exposed.","Lay two or three fillings diagonally across the rice. Do not overfill.","Fold the bottom-left corner over the fillings and continue rolling into a cone. Eat immediately before the nori softens.","For a group meal, place rice, nori, and fillings separately on the table and let each diner assemble one temaki at a time."],"notes":"Use sashimi-grade seafood if serving fish raw; cooked seafood is a good alternative for easier home handling.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["fish","shellfish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Temaki Sushi 手巻き寿司 Japanese food","Temaki Sushi Japanese food"]},{"id":"jp_051","title":"Inari Sushi","japaneseName":"いなり寿司","romanization":"inari-zushi","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":20,"total":45,"servings":8,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan","ingredients":["500 g prepared sushi rice","8 aburaage tofu pouches","250 ml dashi","3 tbsp sugar","3 tbsp soy sauce","2 tbsp mirin","1 tbsp toasted sesame seeds, optional"],"steps":["Blanch aburaage in boiling water for 1 minute, drain, cool enough to handle, and press gently to remove excess oil.","Cut each aburaage piece to form a pocket if needed.","Simmer dashi, sugar, soy sauce, and mirin. Add aburaage and cook gently 10–12 minutes, turning occasionally, until seasoned and most liquid is absorbed.","Cool the pouches in the cooking liquid, then gently squeeze out excess liquid without tearing them.","Mix sesame seeds into sushi rice if desired. Divide rice into eight loose portions.","Open each pouch and fill with rice without packing too tightly. Fold the edges inward and serve seam-side down or open-side up."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Inari Sushi いなり寿司 Japanese food","Inari Sushi Japanese food"]},{"id":"jp_052","title":"Chirashizushi","japaneseName":"ちらし寿司","romanization":"chirashi-zushi","category":"Sushi & Seafood","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":45,"cook":20,"total":65,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"wide serving bowl","ingredients":["700 g prepared sushi rice","3 eggs","1 tsp sugar","pinch of salt","150 g cooked shrimp","120 g sashimi-grade salmon or tuna, optional","100 g cucumber, thin slices","80 g seasoned shiitake mushrooms","60 g blanched snow peas","2 tbsp ikura salmon roe, optional","nori strips and sesame, optional"],"steps":["Prepare and season the sushi rice, then spread it in a wide bowl to cool to room temperature.","Cook the eggs as a very thin omelet, cool, then slice into fine kinshi tamago strips.","Prepare shrimp, cucumber, shiitake, snow peas, and any raw fish. Keep raw seafood chilled until the final assembly.","Gently mix a small portion of shiitake or sesame into the rice if desired, taking care not to mash the grains.","Spread the rice in a serving dish and arrange egg, shrimp, vegetables, and fish attractively over the surface.","Add ikura and nori at the end and serve promptly."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","fish","shellfish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Chirashizushi ちらし寿司 Japanese food","Chirashizushi Japanese food"]},{"id":"jp_053","title":"Tamagoyaki","japaneseName":"卵焼き","romanization":"tamagoyaki","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":10,"total":20,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"tamagoyaki pan or small nonstick skillet","ingredients":["4 large eggs","2 tbsp dashi","1 tbsp sugar","1 tsp soy sauce","1 tsp mirin","pinch of salt","1 tsp neutral oil"],"steps":["Beat eggs with dashi, sugar, soy sauce, mirin, and salt without creating excessive foam. Strain if you want an especially smooth texture.","Heat a tamagoyaki pan or small nonstick skillet over medium-low heat and wipe with a thin film of oil.","Pour in a thin layer of egg. When mostly set but still moist on top, roll it toward one side of the pan.","Oil the exposed pan lightly, pour in another thin layer, lifting the existing roll so uncooked egg flows underneath.","Roll the cooked omelet back across the new layer. Repeat until all egg is used, adjusting heat so it sets without browning heavily.","Shape the hot roll with a bamboo mat if desired, rest 2–3 minutes, then slice."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Tamagoyaki 卵焼き Japanese food","Tamagoyaki Japanese food"]},{"id":"jp_054","title":"Agedashi Tofu","japaneseName":"揚げ出し豆腐","romanization":"agedashi dofu","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":15,"total":35,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"small pot or deep skillet","ingredients":["400 g firm or medium-firm tofu","50 g potato starch","neutral oil for frying, as needed","250 ml dashi","2 tbsp soy sauce","2 tbsp mirin","80 g grated daikon","1 tsp grated ginger","2 scallions, sliced","katsuobushi, optional"],"steps":["Wrap tofu in paper towels and drain under a light weight for 15 minutes, then cut into 8 pieces.","Simmer dashi, soy sauce, and mirin for 2 minutes to make the broth; keep warm.","Pat tofu dry again and coat every side lightly with potato starch just before frying.","Heat 2–3 cm oil to about 175°C. Fry tofu in batches until the coating is crisp and pale golden, about 2–3 minutes.","Drain briefly, place in shallow bowls, and pour warm broth around—not directly over—the crispest top surfaces.","Finish with grated daikon, ginger, scallion, and katsuobushi if using."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","fish"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Agedashi Tofu 揚げ出し豆腐 Japanese food","Agedashi Tofu Japanese food"]},{"id":"jp_055","title":"Horenso Goma-ae","japaneseName":"ほうれん草の胡麻和え","romanization":"horenso no goma-ae","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":5,"total":15,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"pot and mortar","ingredients":["300 g spinach","3 tbsp toasted sesame seeds","1 1/2 tbsp soy sauce","1 tbsp sugar","1 tbsp dashi or water"],"steps":["Bring a pot of water to a boil. Blanch spinach stems first for about 20 seconds, then submerge the leaves and cook another 30–40 seconds.","Transfer immediately to cold water. Squeeze out water firmly but gently, align the stems, and cut into 4 cm lengths.","Grind toasted sesame seeds until fragrant but not completely paste-like.","Mix sesame with soy sauce, sugar, and dashi or water.","Toss spinach with the sesame dressing just before serving so it remains fresh-tasting."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","sesame"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Horenso Goma-ae ほうれん草の胡麻和え Japanese food","Horenso Goma-ae Japanese food"]},{"id":"jp_056","title":"Kinpira Gobo","japaneseName":"きんぴらごぼう","romanization":"kinpira gobo","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":12,"total":27,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"skillet","ingredients":["250 g gobo burdock root","1 small carrot","1 tbsp sesame oil","1 tbsp sugar","1 1/2 tbsp soy sauce","1 tbsp mirin","1 tbsp sake","1 tsp toasted sesame seeds","small pinch chili flakes, optional"],"steps":["Scrub gobo well, cut into fine matchsticks, and place briefly in water while cutting to reduce discoloration. Drain thoroughly. Julienne carrot similarly.","Heat sesame oil in a skillet over medium-high heat. Stir-fry gobo for 2–3 minutes, then add carrot.","Add sugar, sake, and mirin and stir until the vegetables begin to soften.","Add soy sauce and continue stir-frying until the liquid has mostly evaporated and the vegetables are tender with a slight bite.","Finish with sesame seeds and a tiny pinch of chili if desired.","Cool slightly before serving; kinpira is good warm or at room temperature."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","sesame"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Kinpira Gobo きんぴらごぼう Japanese food","Kinpira Gobo Japanese food"]},{"id":"jp_057","title":"Cucumber Sunomono","japaneseName":"きゅうりの酢の物","romanization":"kyuri no sunomono","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":15,"cook":0,"total":20,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"mixing bowl","ingredients":["2 Japanese or Persian cucumbers, thinly sliced","1/2 tsp salt","3 tbsp rice vinegar","1 1/2 tbsp sugar","1 tsp soy sauce","1 tbsp toasted sesame seeds","2 tbsp rehydrated wakame, optional"],"steps":["Slice cucumbers very thinly. Toss with salt and rest 10 minutes.","Squeeze the cucumbers gently but thoroughly to remove excess water.","Stir rice vinegar, sugar, and soy sauce until the sugar dissolves.","Combine cucumber with wakame if using and toss with the dressing.","Chill 5–10 minutes, then sprinkle with sesame just before serving."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy","sesame"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Cucumber Sunomono きゅうりの酢の物 Japanese food","Cucumber Sunomono Japanese food"]},{"id":"jp_058","title":"Chawanmushi","japaneseName":"茶碗蒸し","romanization":"chawanmushi","category":"Side Dishes","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":20,"total":40,"servings":4,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"steamer and heatproof cups","ingredients":["3 large eggs","450 ml dashi, cooled","1 tbsp light soy sauce","1 tbsp mirin","1/2 tsp salt","120 g chicken thigh, small pieces","4 shrimp, peeled and deveined","4 shiitake mushrooms, sliced","4 slices kamaboko","mitsuba, optional"],"steps":["Lightly beat eggs without foaming.","Mix in cooled dashi, soy sauce, mirin, and salt, then strain for a smooth custard.","Divide chicken, shrimp, shiitake, and kamaboko among four heatproof cups.","Pour egg mixture into cups, leaving a little headspace. Remove surface bubbles with a spoon or skewer.","Cover cups loosely with foil. Steam over gentle—not aggressively boiling—water for about 15–18 minutes.","Check the center: the custard should be softly set and clear broth should appear when pierced; the chicken and shrimp must be fully cooked.","Garnish with mitsuba and serve warm."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","shellfish","fish","soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Chawanmushi 茶碗蒸し Japanese food","Chawanmushi Japanese food"]},{"id":"jp_059","title":"Dorayaki","japaneseName":"どら焼き","romanization":"dorayaki","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":20,"total":40,"servings":6,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"nonstick skillet","ingredients":["2 large eggs","80 g sugar","1 tbsp honey","120 g cake flour","1 tsp baking powder","50 ml water","1 tsp neutral oil","300 g sweet red bean paste"],"steps":["Whisk eggs, sugar, and honey until the sugar is mostly dissolved and the mixture looks slightly thickened.","Sift in cake flour and baking powder and fold until smooth. Add water gradually to make a thick but pourable batter. Rest 10 minutes.","Heat a nonstick skillet over low-medium heat and wipe with the thinnest film of oil, then wipe almost all of it away.","Pour small rounds of batter. Cook until bubbles cover the surface and edges look set, about 1–2 minutes, then flip and cook 30–60 seconds.","Cool pancakes under a clean towel so they stay soft.","Sandwich a generous spoonful of red bean paste between two pancakes, matching similar-size pieces."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Dorayaki どら焼き Japanese food","Dorayaki Japanese food"]},{"id":"jp_060","title":"Daifuku Mochi","japaneseName":"大福","romanization":"daifuku","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":10,"total":35,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"steamer or microwave","ingredients":["150 g shiratamako glutinous rice flour","180 ml water","60 g sugar","240 g smooth red bean paste","potato starch for dusting, as needed"],"steps":["Divide red bean paste into 8 balls and chill while making the mochi.","Mix shiratamako and water until smooth, then stir in sugar.","Steam the mixture in a heatproof bowl for about 10–12 minutes, stirring once halfway, until translucent and very sticky. A microwave can also be used in short intervals.","Dust a tray generously with potato starch.","Scrape the hot mochi onto the tray and dust the top; cool just enough to handle.","Divide into 8 pieces. Flatten one piece with starch-dusted fingers, place an anko ball in the center, and stretch the mochi around it.","Pinch the seam closed, place seam-side down, and brush off excess starch. Best eaten the same day."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":[],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Daifuku Mochi 大福 Japanese food","Daifuku Mochi Japanese food"]},{"id":"jp_061","title":"Warabi Mochi","japaneseName":"わらび餅","romanization":"warabi mochi","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":10,"cook":12,"total":40,"servings":4,"difficulty":"Easy","energy":"normal","cleanup":2,"freezer":"no","equipment":"saucepan","ingredients":["80 g warabi-mochiko or warabi starch blend","400 ml water","50 g sugar","50 g kinako roasted soybean flour","20 g sugar for kinako","pinch of salt","kuromitsu black sugar syrup, optional"],"steps":["Mix warabi starch, water, and 50 g sugar in a saucepan until completely smooth before turning on the heat.","Cook over medium-low heat, stirring continuously with a sturdy spatula. The mixture will turn from milky to translucent and very thick.","Continue stirring 2–3 minutes after it becomes translucent so the starch cooks fully.","Spread into a lightly wet shallow tray and cool, then chill 20 minutes; do not freeze.","Mix kinako with 20 g sugar and a pinch of salt. Cut or pinch the chilled mochi into bite-size pieces and coat generously.","Serve with kuromitsu if desired."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["soy"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Warabi Mochi わらび餅 Japanese food","Warabi Mochi Japanese food"]},{"id":"jp_062","title":"Taiyaki","japaneseName":"たい焼き","romanization":"taiyaki","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":25,"total":45,"servings":8,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"taiyaki pan","ingredients":["150 g cake flour","1 tsp baking powder","1/4 tsp baking soda","1 large egg","35 g sugar","180 ml milk","1 tsp neutral oil","240 g sweet red bean paste"],"steps":["Sift flour, baking powder, and baking soda. In another bowl whisk egg, sugar, and milk, then combine with dry ingredients just until smooth. Rest 10 minutes.","Preheat a taiyaki pan over medium-low heat and brush both sides very lightly with oil.","Pour a thin layer of batter into each fish mold, spreading it toward the tail. Add red bean paste in a narrow mound through the center.","Cover the filling with a little more batter, close the pan, and cook about 2–3 minutes.","Flip the pan and cook another 2–3 minutes, adjusting heat to brown the shell without burning it.","Open carefully, remove taiyaki, and cool on a rack for a few minutes so the exterior stays crisp."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten","milk"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Taiyaki たい焼き Japanese food","Taiyaki Japanese food"]},{"id":"jp_063","title":"Japanese Purin","japaneseName":"プリン","romanization":"purin","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":20,"cook":35,"total":120,"servings":6,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"oven and ramekins","ingredients":["80 g sugar for caramel","2 tbsp water","1 tbsp hot water","3 large eggs","2 egg yolks","500 ml whole milk","70 g sugar","1 tsp vanilla extract"],"steps":["Make caramel by heating 80 g sugar with 2 tablespoons water without stirring until amber. Carefully add 1 tablespoon hot water, swirl, and divide among six heatproof cups.","Heat milk with 70 g sugar just until steaming and the sugar dissolves; do not boil.","Whisk eggs and yolks gently. Gradually whisk in warm milk, then vanilla, avoiding excessive foam. Strain the custard.","Pour into caramel-lined cups and cover loosely with foil. Place in a deep baking dish and add hot water halfway up the cups.","Bake at 150°C for about 30–35 minutes until edges are set and centers still tremble slightly.","Cool, refrigerate at least 1 hour, then loosen edges and invert onto plates."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","milk"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Japanese Purin プリン Japanese food","Japanese Purin Japanese food"]},{"id":"jp_064","title":"Castella","japaneseName":"カステラ","romanization":"kasutera","category":"Sweets & Desserts","cuisine":"Japanese","country":"Japan","region":"Japan","countryCode":"JP","recipeType":"Reviewed classic","prep":25,"cook":45,"total":120,"servings":10,"difficulty":"Medium","energy":"normal","cleanup":2,"freezer":"no","equipment":"stand mixer or hand mixer and loaf pan","ingredients":["6 large eggs, room temperature","180 g sugar","2 tbsp honey","2 tbsp warm water","180 g bread flour, sifted","1 tbsp neutral oil for pan"],"steps":["Line a tall rectangular cake pan completely with parchment. Preheat oven to 160°C. Dissolve honey in warm water.","Beat eggs and sugar over a warm-water bath until the mixture is slightly warm, then remove from heat and whip until very thick, pale, and able to hold a ribbon.","Fold in the honey mixture. Sift in bread flour in several additions and fold gently but thoroughly so no dry pockets remain.","Pour batter into the lined pan. Tap lightly and run a skewer through the batter to break large bubbles.","Bake about 40–45 minutes until deep golden and a skewer comes out clean.","While still warm, wrap the cake tightly once it can be handled and rest several hours or overnight; this redistributes moisture and gives castella its characteristic fine, moist crumb. Slice with a sharp knife."],"notes":"A practical home-cooking version. Japanese households and regions may vary in seasoning, garnish, and technique.","collection":"Japanese Kitchen","source":"Bento Japanese Kitchen · reviewed Aug 2026 against current MAFF Japanese Cuisine guidance, Kikkoman Global Cookbook/Washoku lessons, and JNTO food references.","sourceUrls":["https://www.maff.go.jp/e/policies/market/japan-cuisine/index.html","https://www.kikkoman.com/en/cookbook/","https://www.japan.travel/en/things-to-do/eat-and-drink/"],"favorite":false,"builtIn":true,"dietTags":[],"allergens":["egg","gluten"],"spiceLevel":"mild","libraryVersion":8,"createdAt":"2026-08-12T00:00:00.000Z","updatedAt":"2026-08-12T00:00:00.000Z","verifiedAt":"2026-08-12","instructionVersion":5,"instructionStyle":"detailed-concise","photoQueries":["Castella カステラ Japanese food","Castella Japanese food"]}];
